import{_ as e,a as i,b as a,c as t,d as r,e as l,f as s,g as n,h as m,i as p,j as c,k as d,l as u,m as g,n as _,o as f,p as h,q as z,r as v,s as y,t as x,u as b,v as q,w as D,x as S,y as P,z as k,A as w,B as L,C as I,D as T,E as C,F as W,G as A,H as F,I as G,J as N,K as U,L as B,M as V,N as $,O as E,P as K,Q,R as X,S as M,T as O}from"./chunks/M-S-SW-AW-ST13.BF6FVufy.js";import{_ as R}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as J,o as j,c as H,a3 as Y}from"./chunks/framework.g9mfNVRQ.js";const mo=JSON.parse(`{"title":"Usare l'estensione Wear","description":"","frontmatter":{"source_hash":"f17272d683","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/usewear.md","filePath":"it/smartwatch/usewear.md"}`),Z={name:"it/smartwatch/usewear.md"};function oo(eo,o,io,ao,to,ro){return j(),H("div",null,[...o[0]||(o[0]=[Y('<p>Trovi la documentazione di riferimento <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">qui</a>.</p><h2 id="discover-wear-extension" tabindex="-1">Scoprire l&#39;estensione Wear <a class="header-anchor" href="#discover-wear-extension" aria-label="Permalink to &quot;Scoprire l&#39;estensione Wear {#discover-wear-extension}&quot;">​</a></h2><p>xDrip mette a disposizione quattro quadranti nativi.</p><table tabindex="0"><thead><tr><th style="text-align:center;">XDrip</th><th style="text-align:center;">XDrip(BigChart)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+e+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+i+'" style="zoom:75%;"></td></tr><tr><td style="text-align:center;"><strong>XDrip(Large)</strong></td><td style="text-align:center;"><strong>XDrip(Circle)</strong></td></tr><tr><td style="text-align:center;"><img src="'+a+'" style="zoom:75%;"></td><td style="text-align:center;"><img src="'+t+'" style="zoom:75%;"></td></tr></tbody></table><p>I quadranti con grafico hanno alcuni elementi in comune con la schermata principale di xDrip.</p><ol><li>L&#39;ultimo valore di glicemia misurato.<br> La differenza di glicemia rispetto al valore precedente ricevuto.<br> La tendenza rispetto alla misurazione precedente.</li><li>Una riga di stato.</li><li>Un grafico della glicemia.</li></ol><img src="'+r+'" style="zoom:75%;"><p>Un doppio tocco sul grafico cambia la scala temporale.</p><img src="'+l+'" style="zoom:75%;"><p>Poiché l&#39;estensione Wear di xDrip contiene una parte del codice dell&#39;app, troverai sull&#39;orologio alcune voci di menu di xDrip. Le trovi tra le app dell&#39;orologio; alcune sono accessibili anche dal grafico tramite il menu a tre puntini presente su tutti i quadranti.</p><img src="'+R+'" style="zoom:75%;"><h3 id="xdrip-prefs" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs" aria-label="Permalink to &quot;xDrip Prefs. {#xdrip-prefs}&quot;">​</a></h3><p>Questo menu contiene le opzioni di visualizzazione del quadrante.<br> Quando l&#39;orologio è configurato come collector autonomo, sono visibili altre voci. Vedi più avanti.</p><img src="'+s+'" style="zoom:75%;"><p>Il tema scuro mostra uno sfondo nero con testo e grafico bianchi. Disattivandolo ottieni il contrario: sfondo bianco con testo e grafico scuri.</p><img src="'+n+'" style="zoom:75%;"><p>Refresh on change aggiorna il quadrante a ogni cambiamento dei dati (minimo 5 minuti). Se lo disattivi, l&#39;orologio aggiornerà il quadrante ogni minuto (consumerà più batteria).</p><img src="'+m+'" style="zoom:75%;"><p>Show treatment aggiunge i punti dei trattamenti sui quadranti con grafico.</p><img src="'+p+'" style="zoom:75%;"><p>Il formato 24 ore forza la visualizzazione dell&#39;ora in questo formato.</p><img src="'+c+'" style="zoom:75%;"><p>Show date mostra anche la data sul quadrante.</p><img src="'+d+'" style="zoom:75%;"><p>Se l&#39;orologio è configurato per usare la propria lingua, puoi forzarlo a usare le impostazioni del telefono.</p><img src="'+u+'" style="zoom:75%;"><p>I toast sono messaggi a comparsa: puoi attivarli e ottenere informazioni aggiuntive toccando i passi e lo stato sull&#39;orologio.</p><img src="'+g+'" style="zoom:75%;"><p>Se l&#39;orologio lo supporta e hai autorizzato xDrip Prefs. ad accedere ai dati dei sensori dell&#39;orologio, avrai il contapassi sul quadrante e potrai visualizzare i <a href="./../use/display.html">dati dei passi</a> in xDrip sul telefono.</p><img src="'+_+'" style="zoom:75%;"><p>Se l&#39;orologio lo supporta e hai autorizzato xDrip Prefs. ad accedere ai dati dei sensori dell&#39;orologio, avrai la frequenza cardiaca sul quadrante e potrai visualizzare i <a href="./../use/display.html">dati della frequenza cardiaca</a> in xDrip sul telefono.</p><img src="'+f+'" style="zoom:75%;"><p>Se usi un sistema open source a circuito chiuso (come AAPS) che trasmette i dati a xDrip, puoi aggiungere lo stato del loop alla riga di stato.</p><img src="'+h+'" style="zoom:75%;"><p>Per impostazione predefinita il quadrante mostra la batteria del dispositivo che raccoglie i dati come <code>uploader</code> o <code>wear</code>. È una definizione storica che non aggiunge nulla se non usi xDrip come master: non mostrerà il livello di batteria del telefono master né quello di un eventuale bridge, ma solo la batteria del tuo telefono e dell&#39;orologio.</p><img src="'+z+'" style="zoom:75%;"><p>Ti permette di mostrare le schede (avvisi) con uno sfondo uniforme per migliorarne la leggibilità.</p><img src="'+v+'" style="zoom:75%;"><p>Puoi cambiare la dimensione del carattere della riga di stato: 10 o 12 punti.</p><img src="'+y+'" style="zoom:75%;"><p>Puoi cambiare l&#39;intervallo di tempo del grafico, come con il doppio tocco.</p><img src="'+x+'" style="zoom:75%;"><p>In questo menu trovi le personalizzazioni del quadrante circolare.</p><img src="'+b+'" style="zoom:75%;"><p>Colore per i valori bassi.</p><img src="'+q+'" style="zoom:75%;"><p>Su xDrip e xDrip Large, cambia il colore del divisore (riga di stato) per adattarlo allo sfondo.</p><img src="'+D+'" style="zoom:75%;"><p>Force update è disponibile sugli orologi Wear 2.0 e successivi, se disponibile per la versione attuale e attivato come spiegato <a href="./wearinstall.html#wear-os-2x-and-3x">qui</a>.</p><img src="'+S+'" style="zoom:75%;"><p>Demigod è disponibile per gli <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">orologi modificati</a>.</p><img src="'+P+'" style="zoom:75%;"><h3 id="keypad-treatment" tabindex="-1">Keypad Treatment <a class="header-anchor" href="#keypad-treatment" aria-label="Permalink to &quot;Keypad Treatment {#keypad-treatment}&quot;">​</a></h3><p>Keypad Treatment è identico all&#39;<a href="./../use/mainUI.html#treatments">icona della siringa</a> di xDrip.</p><img src="'+k+'" style="zoom:75%;"><img src="'+w+'" style="zoom:75%;"><h3 id="spoken-treatment" tabindex="-1">Spoken treatment <a class="header-anchor" href="#spoken-treatment" aria-label="Permalink to &quot;Spoken treatment {#spoken-treatment}&quot;">​</a></h3><p>Spoken treatment (trattamento vocale) è identico a quello di xDrip.</p><img src="'+L+'" style="zoom:75%;"><img src="'+I+'" style="zoom:75%;"><h3 id="snooze-alert" tabindex="-1">Snooze Alert <a class="header-anchor" href="#snooze-alert" aria-label="Permalink to &quot;Snooze Alert {#snooze-alert}&quot;">​</a></h3><p>Non tutti gli avvisi e gli allarmi sono disponibili sull&#39;orologio.</p><img src="'+T+'" style="zoom:75%;"><p>Su Wear 1.x, gli allarmi e gli avvisi che rimandano all&#39;apertura sul telefono indicano che devi posticiparli dall&#39;app xDrip del telefono.</p><img src="'+C+'" style="zoom:75%;"><p>Su Wear 2.x e successivi, gli avvisi possono comparire come notifiche: dovrai aprire manualmente l&#39;app di sospensione degli allarmi sul telefono o posticiparli dall&#39;app xDrip del telefono.</p><img src="'+W+'" style="zoom:75%;"><h2 id="standalone-collector-mode" tabindex="-1"><a href="./wear.html#standalone-collector-mode">Modalità collector autonomo</a> <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;[Modalità collector autonomo](./wear#standalone-collector-mode) {#standalone-collector-mode}&quot;">​</a></h2><p>Il menu xDrip Prefs. conterrà informazioni aggiuntive riprese da xDrip sul telefono quando i due sono collegati.</p><h4 id="validation" tabindex="-1">Convalida <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Convalida {#validation}&quot;">​</a></h4><p>Un meccanismo di convalida garantisce che entrambi usino le stesse impostazioni. Se l&#39;orologio non accetta la modifica delle impostazioni inviata da xDrip, queste verranno modificate automaticamente per corrispondere alle impostazioni dell&#39;orologio quando i due sono collegati.</p><ol><li>Le impostazioni vengono modificate sul telefono</li><li>Le modifiche vengono inviate all&#39;orologio, quando è collegato</li><li>L&#39;orologio prova ad applicare le modifiche alle impostazioni</li><li>Le impostazioni dell&#39;orologio vengono rimandate al telefono (modificate o no)</li><li>Le impostazioni del telefono vengono aggiornate per riflettere quelle dell&#39;orologio, quando è collegato</li></ol><img src="'+A+'" style="zoom:75%;"><p>Funziona anche nell&#39;altro senso. Se le impostazioni dell&#39;orologio vengono modificate, saranno inviate al telefono quando è collegato. xDrip sul telefono convaliderà le modifiche e le rimanderà all&#39;orologio come conferma.</p><ol><li>Le impostazioni vengono modificate sull&#39;orologio</li><li>Le modifiche vengono inviate al telefono, quando è collegato</li><li>xDrip sul telefono convalida le modifiche alle impostazioni</li><li>Le impostazioni del telefono vengono rimandate all&#39;orologio (convalidate o no)</li><li>Le impostazioni dell&#39;orologio vengono aggiornate per riflettere quelle del telefono, quando è collegato</li></ol><img src="'+F+'" style="zoom:75%;"><h4 id="xdrip-prefs-1" tabindex="-1">xDrip Prefs. <a class="header-anchor" href="#xdrip-prefs-1" aria-label="Permalink to &quot;xDrip Prefs. {#xdrip-prefs-1}&quot;">​</a></h4><p>Quando il collector autonomo è attivo, trovi altre voci nel menu.</p><p>BT collector mostra quale collector della sorgente dati hardware è impostato in xDrip sul telefono.</p><img src="'+G+'" style="zoom:75%;"><p>Enable collector corrisponde all&#39;impostazione in <a href="./wear.html#standalone-collector-mode">Integrazione Wear</a>.</p><img src="'+N+'" style="zoom:75%;"><p>Lo stesso vale per Force collector. Se l&#39;orologio non è collegato al telefono e hai perso la connessione al sensore, puoi attivarlo per forzare un tentativo di riconnessione.</p><img src="'+U+'" style="zoom:75%;"><p>In modalità collector autonomo puoi usare (alcuni) avvisi locali dell&#39;orologio. Verranno posticipati sull&#39;orologio.</p><img src="'+B+'" style="zoom:75%;"><p>Compreso l&#39;avviso di glicemia alta persistente.</p><img src="'+V+'" style="zoom:75%;"><p>Se l&#39;orologio ha un altoparlante, può anche far suonare gli allarmi.</p><img src="'+$+'" style="zoom:75%;"><p>Se ti colleghi a un G5 o G6, troverai altre impostazioni.</p><img src="'+E+'" style="zoom:75%;"><p>Sono la copia delle impostazioni del telefono Impostazioni di debug G5/G6 - Old G5 Collector Settings.</p><img src="'+K+'" style="zoom:75%;"><img src="'+Q+'" style="zoom:75%;"><img src="'+X+'" style="zoom:75%;"><img src="'+M+'" style="zoom:75%;"><p>Force screen on garantisce che l&#39;orologio sia completamente attivo durante la scansione.</p><img src="'+O+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',101)])])}const po=J(Z,[["render",oo]]);export{mo as __pageData,po as default};
